/**
 * Shared helpers for tagging tool-emitted messages with their originating
 * `tool_use` ID and extracting `tool_use` IDs from assistant parent messages.
 */

import type { AssistantMessage, Message } from '../types/message.js'

/**
 * Stamps `sourceToolUseId` onto user messages generated by a tool call.
 */
export function tagMessagesWithToolUseId<T extends Message>(
  messages: readonly T[],
  toolUseId: string,
): T[] {
  return messages.map(msg => {
    if (msg.type === 'user') {
      return {
        ...msg,
        sourceToolUseId: toolUseId,
      }
    }
    return msg
  })
}

/**
 * Finds the matching `tool_use` block ID from an assistant message for a given
 * tool name, falling back to the first `tool_use` block if present.
 */
export function getToolUseIdFromParentMessage(
  parentMessage: AssistantMessage | undefined,
  toolName?: string,
): string | undefined {
  if (!parentMessage || parentMessage.type !== 'assistant') {
    return undefined
  }
  for (const block of parentMessage.message.content) {
    if (block.type === 'tool_use') {
      if (!toolName || block.name === toolName) {
        return block.id
      }
    }
  }
  return undefined
}
